-- Brand <-> sub-category links rebuilt from the 2026-11-10 brand audit, and
-- duplicate brands (same company listed twice for another field) folded into
-- the main brand. Generated by _claude_work/brand-audit/gen_sql.py.

create temp table _brand_links (brand_id uuid, slug text) on commit drop;

-- 1. fold duplicates: products move to the main brand, the duplicate is retired
-- BabySebamed -> Sebamed
update public.products set brand_id = 'babdaa23-4708-42f3-a53f-bd509dc52dd6' where brand_id = 'a45d81b0-fd87-45ba-95e2-ca1067c725e9';
delete from public.brand_categories where brand_id = 'a45d81b0-fd87-45ba-95e2-ca1067c725e9';
update public.brands set deleted_at = now(), is_active = false where id = 'a45d81b0-fd87-45ba-95e2-ca1067c725e9' and deleted_at is null;
