-- 2. replace the links of every audited brand
delete from public.brand_categories bc using _brand_links l where bc.brand_id = l.brand_id;
select distinct l.brand_id, c.id
  from _brand_links l
  join public.categories c on c.slug_en = l.slug and c.depth = 2 and c.deleted_at is null
  join public.brands b on b.id = l.brand_id and b.deleted_at is null
on conflict do nothing;

-- 3. never orphan an existing product: its brand stays linked to its own sub-category
select distinct p.brand_id, split_part(c.path, '/', 2)::uuid
  from public.products p
  join public.categories c on c.id = p.leaf_category_id
 where p.brand_id is not null and p.deleted_at is null and split_part(c.path, '/', 2) <> ''
on conflict do nothing;
